import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Optimized CUDA kernel with register tiling and vectorized loads
cuda_source = """
#include <torch/extension.h>

#define TILE_SIZE 32
#define THREADS_PER_BLOCK 16
#define REG_TILE_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory with padding to avoid bank conflicts
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each block computes a TILE_SIZE x TILE_SIZE output tile
    int blockRow = blockIdx.y * TILE_SIZE;
    int blockCol = blockIdx.x * TILE_SIZE;

    // Each thread computes REG_TILE_SIZE x REG_TILE_SIZE output elements
    float c[REG_TILE_SIZE][REG_TILE_SIZE] = {{0}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tile from A (coalesced access)
        int A_row = blockRow + ty;
        int A_col = t * TILE_SIZE + tx;
        if (A_row < N && A_col < N) {
            As[ty][tx] = A[A_row * N + A_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B (coalesced access)
        int B_row = t * TILE_SIZE + ty;
        int B_col = blockCol + tx;
        if (B_row < N && B_col < N) {
            Bs[ty][tx] = B[B_row * N + B_col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial products with register tiling
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k++) {
            float a = As[ty][k];

            #pragma unroll
            for (int i = 0; i < REG_TILE_SIZE; i++) {
                float b = Bs[k][tx + i * THREADS_PER_BLOCK / REG_TILE_SIZE];
                #pragma unroll
                for (int j = 0; j < REG_TILE_SIZE; j++) {
                    c[i][j] += a * b;
                }
            }
        }

        __syncthreads();
    }

    // Write results to global memory
    #pragma unroll
    for (int i = 0; i < REG_TILE_SIZE; i++) {
        #pragma unroll
        for (int j = 0; j < REG_TILE_SIZE; j++) {
            int row = blockRow + ty + i * THREADS_PER_BLOCK / REG_TILE_SIZE;
            int col = blockCol + tx + j * THREADS_PER_BLOCK / REG_TILE_SIZE;

            if (row < N && col < N) {
                C[row * N + col] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B) {
    // Check inputs
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Set grid and block dimensions
    dim3 threads(THREADS_PER_BLOCK, THREADS_PER_BLOCK);
    dim3 blocks((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
